def square_root(number):
    """
    Compute the integer square root of `number` when it is a perfect square.
    For non-perfect squares or negative input a ValueError is raised.

    This implementation uses binary search and avoids using math or exponentiation.
    """
    if not isinstance(number, int):
        raise ValueError("Input must be an integer")
    if number < 0:
        raise ValueError("Cannot compute square root of negative number")
    if number in (0, 1):
        return number

    low, high = 1, number // 2
    while low <= high:
        mid = (low + high) // 2
        sq = mid * mid
        if sq == number:
            return mid
        if sq < number:
            low = mid + 1
        else:
            high = mid - 1

    raise ValueError("The given number is not a perfect square")
